# A decision helper that encodes the "simplest thing that works" ladder.
def recommend(needs_private_knowledge, needs_live_data_or_actions,
              steps_known_in_advance, high_cost_of_error,
              has_labelled_data, prompting_hit_quality_target):
    plan = ["Start with a strong prompt + examples"]
    if needs_private_knowledge:
        plan.append("Add RAG over the customer's documents")
    if needs_live_data_or_actions:
        plan.append("Give the model tools (API calls) for lookups/actions")
        plan.append("Use a fixed workflow" if steps_known_in_advance
                    else "Use an agent loop with step limits and logging")
    if high_cost_of_error:
        plan.append("Add human review before any action is final")
    if has_labelled_data and not prompting_hit_quality_target:
        plan.append("Consider fine-tuning (only after evals show prompting plateaued)")
    return plan

cases = {
    "HR policy Q&A bot": dict(needs_private_knowledge=True, needs_live_data_or_actions=False,
        steps_known_in_advance=True, high_cost_of_error=False, has_labelled_data=False,
        prompting_hit_quality_target=True),
    "Claims intake: extract fields, check policy, route": dict(needs_private_knowledge=False,
        needs_live_data_or_actions=True, steps_known_in_advance=True, high_cost_of_error=True,
        has_labelled_data=True, prompting_hit_quality_target=True),
    "IT troubleshooting across many systems": dict(needs_private_knowledge=True,
        needs_live_data_or_actions=True, steps_known_in_advance=False, high_cost_of_error=True,
        has_labelled_data=False, prompting_hit_quality_target=True),
}
for name, answers in cases.items():
    print(name)
    for step in recommend(**answers):
        print("   -", step)
    print()

# A thin vertical slice: support ticket -> model -> validated JSON -> route.
import json

CATEGORIES = {"billing", "technical", "account", "other"}
PRIORITIES = {"low", "medium", "high"}

def call_model(prompt):
    """Stand-in for a real LLM call. Swap this for an API call later."""
    text = prompt.split("TICKET:")[1].lower()
    if "charged" in text or "invoice" in text:
        return '{"category": "billing", "priority": "high", "summary": "Billing problem"}'
    if "password" in text or "login" in text:
        return '{"category": "account", "priority": "medium", "summary": "Login issue"}'
    if "crash" in text:
        return 'Sure! Here is the JSON: {"category": "bug", "priority": "urgent"}'  # a bad answer
    return '{"category": "other", "priority": "low", "summary": "General question"}'

PROMPT = """Classify the support ticket. Reply with JSON only:
{{"category": one of {cats}, "priority": "low"|"medium"|"high", "summary": short text}}
TICKET: {ticket}"""

def parse(raw):
    start, end = raw.find("{"), raw.rfind("}")
    try:
        data = json.loads(raw[start:end + 1])
    except ValueError:
        return None, "not valid JSON"
    if data.get("category") not in CATEGORIES:
        return None, f"bad category {data.get('category')!r}"
    if data.get("priority") not in PRIORITIES:
        return None, f"bad priority {data.get('priority')!r}"
    return data, None

def route(ticket):
    raw = call_model(PROMPT.format(cats=sorted(CATEGORIES), ticket=ticket))
    data, err = parse(raw)
    if err:
        return {"category": "other", "priority": "medium", "needs_human": True, "error": err}
    return {**data, "needs_human": False}

tickets = [
    "I was charged twice on my last invoice!",
    "Can't login after resetting my password",
    "The app crashes when I upload a PDF",
    "Do you have an office in Berlin?",
]
for t in tickets:
    print(f"{t[:42]:<44} -> {route(t)}")

# Compare two prompt versions on a golden set, overall and per segment.
from collections import defaultdict

golden = [  # (ticket_id, true_label)
    (1, "billing"), (2, "billing"), (3, "technical"), (4, "technical"), (5, "technical"),
    (6, "account"), (7, "account"), (8, "fraud"), (9, "fraud"), (10, "fraud"),
    (11, "billing"), (12, "technical"),
]
# Predictions recorded from two prompt versions
v1 = {1:"billing",2:"billing",3:"technical",4:"account",5:"technical",6:"account",
      7:"account",8:"fraud",9:"fraud",10:"billing",11:"billing",12:"technical"}
v2 = {1:"billing",2:"billing",3:"technical",4:"technical",5:"technical",6:"account",
      7:"account",8:"fraud",9:"billing",10:"billing",11:"billing",12:"technical"}

def score(preds):
    seg = defaultdict(lambda: [0, 0])
    for tid, truth in golden:
        seg[truth][1] += 1
        seg[truth][0] += preds[tid] == truth
    overall = sum(c for c, n in seg.values()) / len(golden)
    return overall, {k: c / n for k, (c, n) in seg.items()}

o1, s1 = score(v1)
o2, s2 = score(v2)
print(f"{'segment':<10}{'v1':>7}{'v2':>7}")
for k in sorted(s1):
    flag = "  <-- REGRESSION" if s2[k] < s1[k] else ""
    print(f"{k:<10}{s1[k]:>7.0%}{s2[k]:>7.0%}{flag}")
print(f"{'overall':<10}{o1:>7.0%}{o2:>7.0%}")

critical = {"fraud"}
blocked = [k for k in critical if s2[k] < s1[k]]
print("\nShip v2?", "NO, critical segment regressed: " + ", ".join(blocked) if blocked else "yes")

print("\nFailures to read by hand (v2):")
for tid, truth in golden:
    if v2[tid] != truth:
        print(f"  ticket {tid}: expected {truth}, got {v2[tid]}")

# A minimal tool layer: schemas, validation, read/write separation and approval.
ORDERS = {"A-100": {"customer": "acme", "total": 120.0, "status": "delivered"},
          "A-101": {"customer": "acme", "total": 980.0, "status": "delivered"}}

TOOLS = {
    "get_order": {
        "description": "Look up one order by its id, e.g. A-100.",
        "params": {"order_id": str}, "writes": False,
        "fn": lambda order_id: ORDERS.get(order_id) or {"error": f"No order {order_id}. Ids look like A-100."},
    },
    "issue_refund": {
        "description": "Refund part or all of an order. Needs human approval above $200.",
        "params": {"order_id": str, "amount": float}, "writes": True,
        "fn": lambda order_id, amount: {"refunded": amount, "order_id": order_id},
    },
}
audit_log = []

def human_approves(name, args):
    print(f"   [approval requested] {name}{args} -> denied in this demo")
    return False

def dispatch(name, args):
    tool = TOOLS.get(name)
    if not tool:
        return {"error": f"Unknown tool {name}. Available: {list(TOOLS)}"}
    for p, typ in tool["params"].items():
        if not isinstance(args.get(p), typ):
            return {"error": f"Parameter {p} must be {typ.__name__}"}
    if name == "issue_refund":
        order = ORDERS.get(args["order_id"])
        if not order or args["amount"] > order["total"]:
            return {"error": "Refund exceeds order total"}
        if args["amount"] > 200 and not human_approves(name, args):
            return {"error": "Refund needs approval; ticket created for a human"}
    result = tool["fn"](**args)
    audit_log.append((name, args, result))
    return result

# Pretend these calls came from the model's tool-use requests
calls = [
    ("get_order", {"order_id": "A-100"}),
    ("get_order", {"order_id": "100"}),
    ("issue_refund", {"order_id": "A-100", "amount": 40.0}),
    ("issue_refund", {"order_id": "A-101", "amount": 980.0}),
    ("issue_refund", {"order_id": "A-100", "amount": "all"}),
    ("delete_customer", {"id": "acme"}),
]
for name, args in calls:
    print(f"{name}({args})\n   -> {dispatch(name, args)}")
print(f"\nAudit log has {len(audit_log)} executed calls.")
